insert into knowledge.claim
(id,subject_type,subject_id,property_key,value,claimant_type,source_url,observed_at,confidence,status,version,created_at) values
 ('9f40865f-b7c2-59be-8f43-01defa8cbef8','PRODUCT_MODEL','a2818c53-4337-58c4-ab0f-268cbc0d3257','description','"A SOL Nova Unlimited é a máquina topo de linha da Cheyenne, projetada para artistas que exigem precisão e versatilidade. O motor brushless entrega torque consistente em qualquer voltagem, e o curso ajustável permite alternar entre linhas finas, sombreamento e preenchimento sem trocar de equipamento. É uma opção robusta para uso profissional diário."'::jsonb,'MANUFACTURER','https://cheyennetattoo.com/',now(),0.7,'ACTIVE',1,now()),
 ('a9f41ce0-efec-588c-bb5e-fef7a176b046','PRODUCT_MODEL','336d81e8-8bd6-5fb5-a9cf-9e736b13d14f','description','"A HAWK Pen é uma máquina rotativa compacta, leve e silenciosa, voltada para linhas e trabalhos de detalhe. Com curso fixo e construção ergonômica, oferece controle confortável mesmo em sessões longas."'::jsonb,'MANUFACTURER','https://cheyennetattoo.com/',now(),0.7,'ACTIVE',1,now()),
 ('222549ce-8e4c-5b7c-993a-482795177032','PRODUCT_MODEL','2a9f9a38-2468-52bd-a22a-73b7d4fd4522','description','"A HAWK Thunder é uma máquina pen da linha HAWK com curso maior, indicada para preenchimento e trabalho de áreas maiores. Mantém a suavidade característica da linha, com mais entrega de tinta por passada."'::jsonb,'MANUFACTURER','https://cheyennetattoo.com/',now(),0.7,'ACTIVE',1,now()),
 ('f7364da1-1178-530e-bf5d-b41dfc7d1ab6','PRODUCT_MODEL','0f69ff72-f58c-5fe5-96b1-43269bfff944','description','"A Bishop Power Wand Packer é uma máquina pen de alto torque para preenchimento e linhas firmes. O motor brushless e o curso amplo entregam performance consistente, sendo uma das referências do mercado para trabalho de cobertura."'::jsonb,'MANUFACTURER','https://bishoprotary.com/',now(),0.7,'ACTIVE',1,now()),
 ('2ec7d8f2-05a9-5146-a242-e4119f3d528b','PRODUCT_MODEL','86e94463-e84c-5424-a419-cbaecdee0dfb','description','"A Bishop Power Wand Shader é a versão voltada ao sombreamento da linha Power Wand. Oferece resposta suave e controle de transições, ideal para gradações e realismo."'::jsonb,'MANUFACTURER','https://bishoprotary.com/',now(),0.7,'ACTIVE',1,now()),
 ('d4dfb0dd-888b-50d1-96c6-986c99673e38','PRODUCT_MODEL','d3fedba0-c5b6-59e8-aca3-970d4c7a674b','description','"A Bishop Microangelo é uma máquina pen micro, pensada para detalhes finos, retratos e realismo. O curso reduzido permite controle extremo em linhas delicadas e pontilhismo."'::jsonb,'MANUFACTURER','https://bishoprotary.com/',now(),0.7,'ACTIVE',1,now()),
 ('08086c72-830f-5ae8-817b-77a7653e1cbb','PRODUCT_MODEL','e4d37828-e80d-5442-a7fe-edcf177a0329','description','"A Spektra Flux é uma máquina pen wireless de alto desempenho da FK Irons. Com motor brushless e curso ajustável, combina potência e leveza para linhas e sombreamento, e opera com a bateria PowerBolt."'::jsonb,'MANUFACTURER','https://www.fkirons.com/',now(),0.7,'ACTIVE',1,now()),
 ('e76bd80b-9ebe-592c-bca9-8eb392f810f8','PRODUCT_MODEL','cc68e74f-578d-596d-82f3-cd742ab07e58','description','"A Spektra Xion é uma máquina pen compacta e confiável da FK Irons. É uma escolha popular para uso diário, equilibrando peso leve e resposta consistente."'::jsonb,'MANUFACTURER','https://www.fkirons.com/',now(),0.7,'ACTIVE',1,now()),
 ('3202ac67-fe47-5207-b632-02937d690a54','PRODUCT_MODEL','47804996-1d20-535f-afa2-b14e05a26326','description','"A EXO é uma máquina pen ergonômica da FK Irons, com empunhadura confortável e motor brushless. Projetada para versatilidade, atende tanto linhas quanto preenchimento."'::jsonb,'MANUFACTURER','https://www.fkirons.com/',now(),0.7,'ACTIVE',1,now()),
 ('2909f514-0d57-51de-b4e2-242c0d642718','PRODUCT_MODEL','e673326e-cc0f-5d5c-ac9e-f0647216a770','description','"A Mast Tour é uma máquina pen de entrada da Dragonhawk, reconhecida pela boa relação custo-benefício. Com motor brushless e operação simples, é uma porta de acesso confiável ao mundo das máquinas rotativas."'::jsonb,'MANUFACTURER','https://www.dragonhawktattoos.com/',now(),0.7,'ACTIVE',1,now()),
 ('92f0e1b1-c025-53b5-b5f0-a1446390199e','PRODUCT_MODEL','3af9a530-0b1b-5499-abcd-e3b4d1727aeb','description','"A Mast Archer é uma máquina pen leve da Dragonhawk, indicada para linhas e sombreamento. O corpo compacto e a resposta estável a tornam uma opção versátil para diferentes estilos."'::jsonb,'MANUFACTURER','https://www.dragonhawktattoos.com/',now(),0.7,'ACTIVE',1,now()),
 ('f17d7b17-4321-54b6-b64d-ca265176df1c','PRODUCT_MODEL','2b34af9b-a73d-547f-9f68-fae7bcb53223','description','"A Mast Flip é uma máquina pen com design dobrável, pensada para facilitar o transporte. Mesmo no formato compacto, mantém motor brushless e desempenho consistente."'::jsonb,'MANUFACTURER','https://www.dragonhawktattoos.com/',now(),0.7,'ACTIVE',1,now()),
 ('98cfcba3-77b9-5952-9dca-b6a492280367','PRODUCT_MODEL','ce8f3005-5271-5211-b7f7-391ef551a975','description','"A Mast Fold Pro é uma máquina pen dobrável profissional da Mast Tattoo. Reúne a praticidade do formato dobrável com acabamento e torque de linha profissional."'::jsonb,'MANUFACTURER','https://www.masttattoo.com/',now(),0.7,'ACTIVE',1,now()),
 ('130464a6-3813-5fa3-bdf1-276a64eb4d7c','PRODUCT_MODEL','01a01adb-9602-5b1f-b351-28b086064668','description','"A Flite Nano é uma máquina pen wireless da Inkjecta, leve e silenciosa, feita para cartuchos. O motor brushless com curso ajustável oferece precisão em linhas e sombreamento, com a liberdade de operação sem fio."'::jsonb,'MANUFACTURER','https://www.inkjecta.com/',now(),0.7,'ACTIVE',1,now()),
 ('649b6f46-a915-55e6-9849-28762b88a668','PRODUCT_MODEL','58122931-06a1-59fe-8ea1-b8b3a1926097','description','"A Flite Nano Elite é a versão premium da Flite Nano, com corpo em alumínio e maior torque. Mantém a leveza e o silêncio da linha, com acabamento reforçado para uso intenso."'::jsonb,'MANUFACTURER','https://www.inkjecta.com/',now(),0.7,'ACTIVE',1,now()),
 ('b0f3193c-b034-5fc1-bbe7-6c9f3d31231e','PRODUCT_MODEL','c8138a63-3d61-5465-951b-73f188effe16','description','"A Stigma V2 é uma máquina pen compacta da Stigma Rotary. Valorizada pela precisão e pela suavidade, é uma opção consistente para linhas finas e trabalhos de detalhe."'::jsonb,'MANUFACTURER','https://www.stigmarotary.com/',now(),0.7,'ACTIVE',1,now()),
 ('779cc492-f480-5bff-b7fd-62dbbdf4be4b','PRODUCT_MODEL','d2827d19-8508-559d-889a-9c221fb84035','description','"A Critical Torque é uma máquina pen de alto torque da Critical Tattoo, voltada ao preenchimento. O motor brushless entrega potência constante em grandes áreas."'::jsonb,'MANUFACTURER','https://criticaltattoo.com/',now(),0.7,'ACTIVE',1,now()),
 ('4645404a-9c14-5850-bf50-265cac8eb254','PRODUCT_MODEL','bdc77235-d3ae-555e-b08a-83758b3b2d7c','description','"A Kwadron Equalizer é uma máquina pen da Kwadron, equilibrada para linhas e sombreamento. Combina construção sólida e resposta confiável no uso diário."'::jsonb,'MANUFACTURER','https://www.kwadron.pl/',now(),0.7,'ACTIVE',1,now()),
 ('0f1cc2ea-2998-5746-9936-ec91ab38e39e','PRODUCT_MODEL','904acaaf-45c4-55e5-80d9-c4574dc7ec43','description','"A Equaliser Proton é uma máquina pen da Equaliser com motor brushless. Projetada para versatilidade, atende do traço fino ao preenchimento com resposta estável."'::jsonb,'MANUFACTURER','https://www.equaliser.com/',now(),0.7,'ACTIVE',1,now())
